using System;
using System.Collections.Generic;
using System.Collections.Immutable;
using System.Linq;
using System.Text.RegularExpressions;
using System.Threading.Tasks;
using ConsoleTables;
using Extensions.Pack;
using AspNetCore.MinimalApi.Sdk.CodeRules.Api.Controllers;
using Solution.Parser.CSharp;

namespace AspNetCore.MinimalApi.Sdk.CodeRules
{
    [TestCategory("Coding-Rules")]
    [TestCategory("API - Controllers")]
    [TestClass]
    public class RJIT_CR_API_C_00027 : ControllerTestBase
    {
        private static Regex genericTypeRegex = new Regex(@"<([^>]*)>");

        [TestMethod]
        public void Response_Should_Be_A_Custom_Type_With_Response_Postfix()
        {
            var missingResponsePostfix = (from controller in Controllers
                                          where controller.Name.DoesNotContain("Alive")
                                          from method in controller.Methods
                                          let returnType = genericTypeRegex.Match(method.ReturnParameter).Groups[1].Value
                                          where method.ReturnParameter != "ActionResult" &&
                                                method.ReturnParameter != nameof(Task) &&
                                                method.ReturnParameter != "Task<ActionResult>" &&
                                                method.ReturnParameter != "Task<IActionResult>" &&
                                                method.ReturnParameter != "Task<FileStreamResult>" &&
                                                method.ReturnParameter.DoesNotContain("Response")
                                          where method.ReturnParameter != "ActionResult" &&
                                                method.ReturnParameter != nameof(Task) &&
                                                method.ReturnParameter != "Task<ActionResult>" &&
                                                method.ReturnParameter != "Task<IActionResult>" &&
                                                method.ReturnParameter != "Task<FileStreamResult>" &&
                                                method.ReturnParameter.DoesNotContain("Response")
                                          select new
                                          {
                                              Error = $@"
Controller Method:  {method.Name} have not a valid response type. Use custom record types for. No primitive .Net types
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
Response Type:      {method.ReturnParameter}
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
Sample:             Task<{method.Name.Replace("Async", string.Empty)}Response>
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
Method:         

{method.MethodValue.FormatSyntaxTree()}
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
Sample:

{method.MethodValue.Replace(method.ReturnParameter, $"Task<{method.Name.Replace("Async", string.Empty)}Response>")
                   .Replace($"typeof({returnType})", $"typeof({method.Name.Replace("Async", string.Empty)}Response)")
                   .FormatSyntaxTree()}
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

Description:    When using native types like 'string', 'int', 'IEnumerable', you will not able to extend this endpoint without breaking the interface
                For this reason it makes sense to have custom 'Response' objects. The you can extend the API without breaking it
"
                                          }).ToImmutableList();


            Assert.IsTrue(missingResponsePostfix.IsEmpty(),
                @$"
Documentation: {DocumentationDomain}#RJIT_CR_API_C_00027

Response type is not following convention:{Environment.NewLine}{missingResponsePostfix.Select(e => e.Error).Flatten(Environment.NewLine)}");
        }
    }
}
